import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读一：乾坤至师比 · 04 蒙：如何问、如何教、如何养成至06 讼：争执的边界与开端","description":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","frontmatter":{"title":"六十四卦详读一：乾坤至师比 · 04 蒙：如何问、如何教、如何养成至06 讼：争执的边界与开端","description":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","splitFrom":"life/personal/yijing/hexagrams-01-08.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读一：乾坤至师比","summary":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读一：乾坤至师比 · 01 乾：刚健也要知进退至03 屯：初生之难与建立秩序","link":"/life/personal/yijing/hexagrams-01-08-part-01"},"next":{"text":"六十四卦详读一：乾坤至师比 · 07 师：动众必须承担责任至读后比较与自测","link":"/life/personal/yijing/hexagrams-01-08-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读一：乾坤至师比 · 01 乾：刚健也要知进退至03 屯：初生之难与建立秩序","link":"/life/personal/yijing/hexagrams-01-08-part-01"},"next":{"text":"六十四卦详读一：乾坤至师比 · 07 师：动众必须承担责任至读后比较与自测","link":"/life/personal/yijing/hexagrams-01-08-part-03"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-01-08-part-02.md","filePath":"life/personal/yijing/hexagrams-01-08-part-02.md"}'),o={name:"life/personal/yijing/hexagrams-01-08-part-02.md"};function s(i,t,d,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读一-乾坤至师比-·-04-蒙-如何问、如何教、如何养成至06-讼-争执的边界与开端" tabindex="-1">六十四卦详读一：乾坤至师比 · 04 蒙：如何问、如何教、如何养成至06 讼：争执的边界与开端 <a class="header-anchor" href="#六十四卦详读一-乾坤至师比-·-04-蒙-如何问、如何教、如何养成至06-讼-争执的边界与开端" aria-label="Permalink to &quot;六十四卦详读一：乾坤至师比 · 04 蒙：如何问、如何教、如何养成至06 讼：争执的边界与开端&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-01-08">返回分篇目录</a></p><p>这一组从天地、生长与启蒙，进入等待、争讼、组织与亲比。卦序提供阅读线索，并不是每个人都必须按顺序经历的人生阶段。先读卦辞与《大象》，再把六爻自下而上读一遍，留意同一卦里为什么既有“吉”，又有“凶”。</p><p>本文实际对读维基文库《周易》各卦及王弼注、孔颖达疏《周易正义》对应篇。引文保留繁体及“无”等古字，标点为便于阅读所加；网上录文的异体、断句与古注解释并不完全一致，下文必要时说明。表格左栏是古籍原文，右栏及“读法”是本篇白话概括，不是古人原句。古代占筮判断属于其历史语境，不能当作科学预测；君臣、婚姻与性别秩序也不直接作为现代规范。</p><h2 id="gua-04" tabindex="-1">04 蒙：如何问、如何教、如何养成 <a class="header-anchor" href="#gua-04" aria-label="Permalink to &quot;04 蒙：如何问、如何教、如何养成 {#gua-04}&quot;">​</a></h2><p><strong>卦符：䷃　上卦：艮 ☶（山、止）　下卦：坎 ☵（水、险）。</strong></p><p><strong>卦辞原文</strong>：蒙：亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。</p><p><strong>白话概括</strong>：山下有险，前进与退回都未看清，是蒙昧的处境。卦辞保留问筮语言，也被古传展开为启蒙关系。“初筮告”不应被改造成不准追问的权威话术；王弼、孔颖达还从讲授者反复迟疑、让学习者更困惑的方向解释“渎”。学习意愿、说明的清楚与守正缺一不可。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：發蒙，利用刑人，用說桎梏，以往吝。</td><td>涉及刑罚、解除桎梏的古代图景，“说”读脱。古注明确说刑罚不可长用，不能把它作为今日体罚教育的依据。</td></tr><tr><td>九二：包蒙吉，納婦吉，子克家。</td><td>能包容蒙昧者，承接关系并承担事务。启蒙不是先要求对方已经成熟；“克家”是能够担负家事。</td></tr><tr><td>六三：勿用取女，見金夫，不有躬，无攸利。</td><td>以婚姻场景警告失去自持。“金夫”的所指有不同说法；不应将古代对某一爻的判断扩大成对女性的评价。</td></tr><tr><td>六四：困蒙，吝。</td><td>与明实之助隔绝，困于无知。不是说暂时不懂可耻，而是提示闭塞、孤立会加深困境。</td></tr><tr><td>六五：童蒙，吉。</td><td>愿意虚心受教，反而吉。童蒙是可成长的状态，不是天生低人一等。</td></tr><tr><td>上九：擊蒙，不利為寇，利禦寇。</td><td>纠正蒙昧有边界：可以防御侵害，不能自己变成侵害者。过度强制会背离教养。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“山下出泉，蒙；君子以果行育德。”</p><p><strong>解释</strong>：泉刚出山，去向尚待形成；行动要逐步果决，德性也要养成。王、孔将果行与育德分别展开，表明明确回应与平日涵养各有作用，不能只练口头答案。</p><p><strong>整体读法与误区</strong>：蒙不是一张“老师永远正确”的证书。九二包蒙、六五童蒙相互映照，说明教与学需要接纳和回应；初六、上九则限制惩戒的扩张。面对实际问题，可以把阅读所得用于整理提问、区分事实与推测、检验理解，但不能以“你再问就是亵渎”来拒绝合理质疑。</p><p><strong>细读线索</strong>：九二与六五是一组值得反复读的关系：前者能包，后者愿受；只有讲授能力、没有学习意愿，或者只有热心、没有能解决疑惑的内容，都不足以完成启蒙。六四困蒙则呈现远离可求教者的状态。初爻与上爻使用更强烈的刑、击语汇，却分别受到以往吝与不利为寇的限制。把这些限制一起读，比只摘一句利用刑人更能保留全卦的分寸。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%92%99" target="_blank" rel="noopener noreferrer">《周易·蒙》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/01%E8%92%99" target="_blank" rel="noopener noreferrer">《周易正义·上经乾传卷一·蒙》</a>。</p><h2 id="gua-05" tabindex="-1">05 需：等待中的准备与距离 <a class="header-anchor" href="#gua-05" aria-label="Permalink to &quot;05 需：等待中的准备与距离 {#gua-05}&quot;">​</a></h2><p><strong>卦符：䷄　上卦：坎 ☵（水、险）　下卦：乾 ☰（天、健）。</strong></p><p><strong>卦辞原文</strong>：需：有孚，光亨。貞吉，利涉大川。</p><p><strong>白话概括</strong>：“需”是等待；有力量而险在前，不应立刻冲进去。《正义》把诚信与中正视为等待得以成立的条件。卦辞又说利涉大川，表示等待服务于合宜行动，并非永远延期。不能把“有孚”理解成只要相信好运就会来，也不能把“利涉”当作不需准备的许可。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：需于郊，利用恆，无咎。</td><td>在远郊等待，与险境保持距离，守住常态。此时主动不靠近危险，本身就是行动。</td></tr><tr><td>九二：需于沙，小有言，終吉。</td><td>已接近水边，可能出现议论与摩擦，仍可凭适当的等待得到较好结果。小有言不是必然的大灾。</td></tr><tr><td>九三：需于泥，致寇至。</td><td>更靠近险处，陷入泥泞并招致侵害。自己所处的位置会增加风险，不能一律归因于外界恶意。</td></tr><tr><td>六四：需于血，出自穴。</td><td>身处伤害与险陷之中，开始脱离穴处。古注结合顺从时势解释出险，并非说见血就会转运。</td></tr><tr><td>九五：需于酒食，貞吉。</td><td>在较稳定的位置维持饮食与休养，仍以守正为条件。安顿生活不是放纵宴饮。</td></tr><tr><td>上六：入于穴，有不速之客三人來，敬之終吉。</td><td>不请自来的力量进入局面，以敬慎应对而有善终。古注把三人联系下卦三阳，不必认定现实必来三位客人。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“雲上於天，需；君子以飲食宴樂。”</p><p><strong>解释</strong>：云气已升而雨尚未下，君子在等待中保持生活与身心秩序。这里的宴乐与卦中反复出现的险相伴，提醒读者：焦虑并不能替代准备，恢复体力与维持关系也是有意义的工作。</p><p><strong>整体读法与误区</strong>：郊、沙、泥、血构成危险距离逐渐变化的意象；读时要注意不是等得越久越有利，而是在哪里等、以什么状态等。与<a href="/life/personal/yijing/hexagrams-01-08-part-02#gua-06">讼卦</a>相比，同样有乾与坎，位置交换就改变叙述方向。等待是否合理，应另看现实证据、期限与可采取的措施，卦辞不能代替事实判断。</p><p><strong>细读线索</strong>：需的地理意象不能简单换算成等待天数。郊与沙的差异是距离，泥表现行动开始受阻，血则把危险转为身体损害；这是一种逐步逼近的叙事。九五写酒食，表明处于同一险卦也可以有相对可安顿的位置。上六的敬又让回应方式成为转机。读时可先画出这些不同场景，再问每一爻究竟是在主动留距、已经受困，还是面对新的来者。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%80" target="_blank" rel="noopener noreferrer">《周易·需》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E9%9C%80" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·需》</a>。</p><h2 id="gua-06" tabindex="-1">06 讼：争执的边界与开端 <a class="header-anchor" href="#gua-06" aria-label="Permalink to &quot;06 讼：争执的边界与开端 {#gua-06}&quot;">​</a></h2><p><strong>卦符：䷅　上卦：乾 ☰（天、健）　下卦：坎 ☵（水、险）。</strong></p><p><strong>卦辞原文</strong>：訟：有孚，窒，惕，中吉，終凶。利見大人，不利涉大川。</p><p><strong>白话概括</strong>：真实意见受阻，人因而恐惧争执。《正义》尤其强调即使自认为理直，争讼若无限延长也有代价；“中吉”被解释为中途适可而止。“利见大人”则指向中正听断的人。此处不是现代法律意见，更不是要求受害者放弃权利，而是分析把冲突推到极限的风险。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：不永所事，小有言，終吉。</td><td>不让争端持久扩大，虽有少量争辩，最终较好。解决分歧不等于每句话都要赢。</td></tr><tr><td>九二：不克訟，歸而逋，其邑人三百戶无眚。</td><td>争而不能胜，退回避开，使所属人群免于牵连。三百户是古代意象，不是现代损失计算。</td></tr><tr><td>六三：食舊德，貞厲，終吉。或從王事，无成。</td><td>安于已有责任与基础，谨慎守正；参与王事而不自专其功。古注带有君臣秩序，需与今日平等权利区分。</td></tr><tr><td>九四：不克訟，復即命渝，安貞吉。</td><td>不再强争，返回正当安排并改变原来的争心，安于守正而吉。承认局面需要改变不是羞辱。</td></tr><tr><td>九五：訟，元吉。</td><td>处于中正听讼的位置，可以妥善裁断。它并非证明每个身在高位的裁判天然公正。</td></tr><tr><td>上九：或錫之鞶帶，終朝三褫之。</td><td>即使争得象征荣誉的带饰，也可能很快被剥夺。靠争胜获得的承认未必稳定。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“天與水違行，訟；君子以作事謀始。”</p><p><strong>解释</strong>：天与水取相背而行之象，提醒在事情开始时就想清约定、权限和可能分歧。古传并非只讨论争执发生之后怎么办，也把视线放到争端如何形成。</p><p><strong>整体读法与误区</strong>：全卦多次出现“不克讼”，重点不是崇拜输赢，而是承认争执会影响旁人、资源与长期秩序。九五的吉来自中正裁断，不能拿它替某一方预定胜诉；上九则拆解“赢到头便是最好”的想象。现代可借此反思协商机制，但具体维权仍须根据事实与现行制度。</p><p><strong>细读线索</strong>：讼卦把说理与好争分开：卦辞承认有孚，即可能确有实情，却仍要求惕。这使它不像简单的息事宁人，也不像只要自认有理便应斗到底。初六终吉与上九三褫尤其适合首尾对读：前者减少持续争执，后者即使得到荣服仍失去稳定承认。九五的听断责任又让我们看到，解决冲突不只靠当事人退让，还需要能够查明和裁断的公正位置。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A8%9F" target="_blank" rel="noopener noreferrer">《周易·讼》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E8%A8%9F" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·讼》</a>。</p>',34)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
